// core/scene/include/CAD_0/scene/scene.hpp
//
// Scene — a collection of named nodes with transforms. Two kinds of
// node (ADR-0002 honest dispatch — a node is ONE thing, never a fake
// other thing):
//
//   * Sdf  — parametric/analytic body (SDFBody) + optional shape factory
//            for interactive editing; the display mesh is a tessellation
//            CACHE regenerated by update_meshes().
//   * Mesh — imported geometry (TriangleMesh) as a first-class payload;
//            there is no body to evaluate, no builder/params/factory, and
//            update_meshes() SKIPS the node: its "cached mesh" IS the
//            geometry (see display_mesh()).
//
#pragma once

#include "CAD_0/sdf/field.hpp"
#include "CAD_0/sdf/primitives.hpp"
#include "CAD_0/sdf/operators.hpp"
#include "CAD_0/sdf/transforms.hpp"
#include "CAD_0/sdf/mesh_extract.hpp"
#include "CAD_0/math/vec.hpp"
#include "CAD_0/math/mat.hpp"
#include "CAD_0/geometry/transform.hpp"

#include <cstdint>
#include <functional>
#include <map>
#include <string>
#include <variant>
#include <vector>

namespace CAD_0::scene {

// A parameter value that can be edited from the property panel.
using ParamValue = std::variant<float, std::string, bool>;

// A shape factory: given the current parameters, rebuild the SDFBody.
// This allows interactive editing — change a radius, the body is rebuilt.
using ShapeFactory = std::function<sdf::SDFBody(const std::map<std::string, ParamValue>&)>;

// What a node IS (ADR-0002: one representation, honestly dispatched).
enum class NodeKind : std::uint8_t {
    Sdf,   // body-evaluating parametric/analytic shape
    Mesh,  // imported TriangleMesh payload — no SDF semantics
};

struct SceneNode {
    std::uint32_t id{0};
    std::string name;
    NodeKind kind{NodeKind::Sdf};

    // Sdf-kind payload: the signed-distance body (never touched for
    // Mesh-kind nodes).
    sdf::SDFBody body;
    geometry::Transform transform{};
    bool visible{true};

    // Sdf-kind tessellation cache (written by update_meshes).
    sdf::TriangleMesh cached_mesh;
    bool mesh_dirty{true};

    // Mesh-kind payload: THE geometry (imported STL/OBJ). Never touched
    // for Sdf-kind nodes. update_meshes() skips Mesh nodes by kind —
    // nothing about an imported mesh is ever re-tessellated.
    sdf::TriangleMesh mesh;

    // The mesh every consumer (viewport, export, bindings) should see:
    // the tessellation cache for Sdf nodes, THE geometry for Mesh
    // nodes. This is the honest accessor — code that assumes an SDF
    // body must dispatch on `kind`, never on "has cached_mesh".
    const sdf::TriangleMesh& display_mesh() const noexcept {
        return kind == NodeKind::Mesh ? mesh : cached_mesh;
    }

    // Shape factory + parameters for interactive editing.
    // When params change, the body is rebuilt via the factory.
    // Meaningful for Sdf-kind nodes only.
    ShapeFactory factory;
    std::map<std::string, ParamValue> params;

    // Name of the registered NodeBuilder that created this node (e.g.
    // "sphere"), persisted by the native format so a saved project
    // round-trips its editing metadata. Empty for non-parametric nodes.
    // See ADR-0007 / io/native.hpp.
    std::string builder;

    // Rebuild the SDF body from the factory + current params.
    // Sdf-kind only (a Mesh node has no factory — nothing to rebuild).
    void rebuild_body() {
        if (kind == NodeKind::Mesh || !factory) return;
        body = factory(params);
        mesh_dirty = true;
    }

    // Set a parameter and rebuild if a factory exists.
    // Sdf-kind only — parametric editing does not apply to imported
    // meshes (their geometry is data, not a parametric recipe).
    void set_param(const std::string& key, ParamValue value) {
        if (kind == NodeKind::Mesh) return;
        params[key] = std::move(value);
        rebuild_body();
    }
};

enum class SceneChange {
    NodeAdded,
    NodeRemoved,
    NodeModified,
    NodeVisibilityChanged,
    SceneCleared,
};

using SceneChangeCallback = std::function<void(SceneChange, std::uint32_t)>;

class Scene {
public:
    Scene() = default;

    std::uint32_t add_node(const std::string& name, sdf::SDFBody body) {
        SceneNode node;
        node.id = next_id_++;
        node.name = name.empty() ? ("Shape_" + std::to_string(node.id)) : name;
        node.body = std::move(body);
        node.mesh_dirty = true;
        nodes_.push_back(std::move(node));
        notify(SceneChange::NodeAdded, nodes_.back().id);
        return nodes_.back().id;
    }

    // Add a node with a shape factory for interactive editing.
    std::uint32_t add_node(const std::string& name, sdf::SDFBody body,
                           ShapeFactory factory, std::map<std::string, ParamValue> params) {
        SceneNode node;
        node.id = next_id_++;
        node.name = name.empty() ? ("Shape_" + std::to_string(node.id)) : name;
        node.body = std::move(body);
        node.factory = std::move(factory);
        node.params = std::move(params);
        node.mesh_dirty = true;
        nodes_.push_back(std::move(node));
        notify(SceneChange::NodeAdded, nodes_.back().id);
        return nodes_.back().id;
    }

    // Add an imported-mesh node. The geometry is the payload (kind =
    // Mesh): no body, no factory, no params; update_meshes() skips it —
    // display_mesh() IS the geometry. mesh_dirty stays false (nothing
    // ever needs re-tessellating).
    std::uint32_t add_node(const std::string& name, sdf::TriangleMesh mesh) {
        SceneNode node;
        node.id = next_id_++;
        node.name = name.empty() ? ("Mesh_" + std::to_string(node.id)) : name;
        node.kind = NodeKind::Mesh;
        node.mesh = std::move(mesh);
        node.mesh_dirty = false;
        nodes_.push_back(std::move(node));
        notify(SceneChange::NodeAdded, nodes_.back().id);
        return nodes_.back().id;
    }

    // Set a parameter on a node (triggers rebuild + re-tessellation).
    // Sdf-kind only (Mesh nodes have no parametric recipe — the call is
    // a no-op; the UI keeps mesh property panels read-only).
    void set_node_param(std::uint32_t id, const std::string& key, ParamValue value) {
        if (auto* n = get_node_mut(id)) {
            n->set_param(key, std::move(value));
            notify(SceneChange::NodeModified, id);
        }
    }

    bool remove_node(std::uint32_t id) {
        auto it = std::find_if(nodes_.begin(), nodes_.end(),
            [&](const SceneNode& n) { return n.id == id; });
        if (it == nodes_.end()) return false;
        nodes_.erase(it);
        notify(SceneChange::NodeRemoved, id);
        return true;
    }

    const SceneNode* get_node(std::uint32_t id) const {
        auto it = std::find_if(nodes_.begin(), nodes_.end(),
            [&](const SceneNode& n) { return n.id == id; });
        return (it != nodes_.end()) ? &(*it) : nullptr;
    }

    SceneNode* get_node_mut(std::uint32_t id) {
        auto it = std::find_if(nodes_.begin(), nodes_.end(),
            [&](const SceneNode& n) { return n.id == id; });
        return (it != nodes_.end()) ? &(*it) : nullptr;
    }

    void mark_dirty(std::uint32_t id) {
        if (auto* n = get_node_mut(id)) {
            n->mesh_dirty = true;
            notify(SceneChange::NodeModified, id);
        }
    }

    void set_visible(std::uint32_t id, bool visible) {
        if (auto* n = get_node_mut(id)) {
            n->visible = visible;
            notify(SceneChange::NodeVisibilityChanged, id);
        }
    }

    void clear() {
        nodes_.clear();
        notify(SceneChange::SceneCleared, 0);
    }

    const std::vector<SceneNode>& nodes() const noexcept { return nodes_; }
    std::size_t size() const noexcept { return nodes_.size(); }
    bool empty() const noexcept { return nodes_.empty(); }

    // ---- Deserialization support (ADR-0007 / native format) ----

    // Install a fully-formed node during deserialization, keeping its
    // original id. next_id_ is bumped past the restored id. Fires a
    // NodeAdded notification like add_node() so the UI stays in sync.
    void restore_node(SceneNode node) {
        const std::uint32_t id = node.id;
        nodes_.push_back(std::move(node));
        if (next_id_ <= id) next_id_ = id + 1;
        notify(SceneChange::NodeAdded, id);
    }

    // Next id that add_node() will hand out. Persisted by the native
    // format so ids keep growing monotonically across save/load.
    std::uint32_t next_id() const noexcept { return next_id_; }

    // Set the next id (post-load). Clamped so it never collides with an
    // existing node id.
    void set_next_id(std::uint32_t next) {
        for (const auto& n : nodes_)
            if (next <= n.id) next = n.id + 1;
        next_id_ = next;
    }

    // Index-based access (for Python bindings — avoids vector copy issues
    // since SceneNode contains move-only SDFBody).
    std::size_t node_count() const noexcept { return nodes_.size(); }
    SceneNode* node_at(std::size_t index) {
        if (index >= nodes_.size()) return nullptr;
        return &nodes_[index];
    }
    const SceneNode* node_at(std::size_t index) const {
        if (index >= nodes_.size()) return nullptr;
        return &nodes_[index];
    }

    math::Bboxf bounds() const {
        math::Bboxf b;
        for (const auto& n : nodes_) {
            if (!n.visible) continue;
            if (n.kind == NodeKind::Mesh) {
                // Imported geometry: bounds over the payload positions.
                for (const auto& p : n.mesh.positions) b.expand(p);
            } else {
                b.expand(n.body.bounds());
            }
        }
        return b;
    }

    void update_meshes(std::uint32_t resolution = 48) {
        for (auto& n : nodes_) {
            // Mesh nodes are skipped BY KIND: their "cached mesh" is the
            // geometry itself — re-tessellating (or even touching) it
            // would corrupt the imported data.
            if (n.kind == NodeKind::Mesh) continue;
            if (n.mesh_dirty && n.visible) {
                n.cached_mesh = sdf::marching_cubes(n.body, resolution, true);
                n.mesh_dirty = false;
            }
        }
    }

    void set_change_callback(SceneChangeCallback cb) {
        callback_ = std::move(cb);
    }

private:
    std::vector<SceneNode> nodes_;
    std::uint32_t next_id_{1};
    SceneChangeCallback callback_;

    void notify(SceneChange change, std::uint32_t node_id) {
        if (callback_) callback_(change, node_id);
    }
};

} // namespace CAD_0::scene
